"""A small HCL reader, expression evaluator, and layout engine.

The reader keeps source locations, while the formatter deliberately works on
lexical tokens: formatting is useful even for an unfinished configuration.
"""
from dataclasses import dataclass, field
import json
import os
import re
import math
from errors import AtlasError, quote

@dataclass
class Token:
    value: str
    kind: str
    start: int
    end: int
    line: int
    col: int


def lex(text, comments=False):
    out=[]; i=0; line=1; col=1
    def add(end,kind):
        nonlocal i,line,col
        s=text[i:end]
        if kind not in ('space','comment') or (kind=='comment' and comments):
            out.append(Token(s,kind,i,end,line,col))
        n=s.count('\n')
        if n: line+=n;col=len(s.rsplit('\n',1)[-1])+1
        else: col+=len(s)
        i=end
    while i<len(text):
        ch=text[i]
        if ch in ' \t\r':
            j=i+1
            while j<len(text) and text[j] in ' \t\r':j+=1
            add(j,'space')
        elif ch=='\n':add(i+1,'nl')
        elif ch=='#' or text.startswith('//',i):
            j=text.find('\n',i)
            add(len(text) if j<0 else j,'comment')
        elif text.startswith('/*',i):
            j=text.find('*/',i+2);add(len(text) if j<0 else j+2,'comment')
        elif ch=='"':
            j=i+1; template_depth=0
            while j<len(text):
                if text[j]=='\\':j+=2;continue
                # Quoted strings within ${...} do not close the outer string.
                if text.startswith('${',j) and (j==0 or text[j-1]!='$'):
                    depth=1;j+=2
                    while j<len(text) and depth:
                        if text[j]=='"':
                            j+=1
                            while j<len(text) and text[j]!='"':j+=2 if text[j]=='\\' else 1
                        elif text[j]=='{':depth+=1
                        elif text[j]=='}':depth-=1
                        j+=1
                    continue
                if text[j]=='"':j+=1;break
                j+=1
            add(min(j,len(text)),'string')
        elif text.startswith('<<',i):
            m=re.match(r'<<-?([\w-]+)[^\n]*\n',text[i:])
            if m:
                tag=m.group(1);end=i+m.end()
                close=re.search(r'(?m)^[ \t]*'+re.escape(tag)+r'[ \t]*(?=\n|$)',text[end:])
                add(end+close.end() if close else len(text),'heredoc')
            else:add(i+2,'op')
        elif ch.isalpha() or ch=='_':
            j=i+1
            while j<len(text) and (text[j].isalnum() or text[j] in '_-'):j+=1
            add(j,'id')
        elif ch.isdigit():
            m=re.match(r'(?:\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)',text[i:])
            add(i+len(m.group()),'num')
        else:
            m=next((x for x in ('...','=>','==','!=','<=','>=','&&','||','::') if text.startswith(x,i)),ch)
            add(i+len(m),'op')
    return out


def _space(prev,cur,prevprev=None):
    if not prev:return False
    a,b=prev.value,cur.value
    if cur.kind=='comment':return True
    if a=='.' or b=='.' or b=='...':return False
    if b in (',',')',']'):return False
    if a in ('(', '['):return False
    if a=='{' and b=='}':return False
    if b=='(' and prev.kind=='id':return False
    if b=='[' and (prev.kind in ('id','string') or a in (']',')')):return False
    if a=='!' or (a=='-' and (prevprev is None or prevprev.value in ('=','(',',','[',':','?','+','-','*','/','!','==','>','<','{'))):return False
    return True


def format_hcl(text):
    tokens=lex(text,True)
    lines=[];cur=[];depth=0
    def flush(newline):
        nonlocal cur,depth
        if not cur:
            lines.append({'text':'','eq':None,'comment':None,'indent':depth,'break':True,'nl':newline});return
        startdepth=depth
        k=0
        while k<len(cur) and cur[k].value in ('}',']',')'):
            startdepth-=1;k+=1
        startdepth=max(0,startdepth)
        content='';eqpos=None;cmpos=None;pd=None;pp=None;localdepth=0
        for t in cur:
            if _space(pd,t,pp):content+=' '
            if t.value=='=' and eqpos is None and localdepth==0:eqpos=len(content)
            if t.kind=='comment' and cmpos is None:cmpos=len(content)
            content+=t.value
            if t.kind not in ('string','heredoc','comment'):
                if t.value in ('{','[','('):localdepth+=1;depth+=1
                if t.value in ('}',']',')'):localdepth-=1;depth-=1
            pp,pd=pd,t
        depth=max(0,depth)
        # The '=' of an attribute at the line's own level defines its alignment group.
        if eqpos is not None:
            lhs=content[:eqpos].rstrip()
            if not re.match(r'^[\w-]+$',lhs,re.UNICODE):eqpos=None
        lines.append({'text':content,'eq':eqpos,'comment':cmpos,'indent':startdepth,'break':eqpos is None,'nl':newline})
        cur=[]
    for t in tokens:
        if t.kind=='nl':flush(True)
        else:cur.append(t)
    if cur:flush(False)
    i=0
    while i<len(lines):
        if lines[i]['eq'] is None:i+=1;continue
        j=i+1
        while j<len(lines) and lines[j]['eq'] is not None and lines[j]['indent']==lines[i]['indent']:j+=1
        w=max(x['eq'] for x in lines[i:j])
        for x in lines[i:j]:
            d=w-x['eq'];x['text']=x['text'][:x['eq']]+' '*d+x['text'][x['eq']:]
            if x['comment'] is not None:x['comment']+=d
            x['eq']=w
        i=j
    i=0
    while i<len(lines):
        if lines[i]['comment'] is None or lines[i]['comment']==0:i+=1;continue
        j=i+1
        while j<len(lines) and lines[j]['comment'] not in (None,0) and lines[j]['indent']==lines[i]['indent']:j+=1
        w=max(x['comment'] for x in lines[i:j])
        for x in lines[i:j]:
            p=x['comment'];x['text']=x['text'][:p]+' '*(w-p)+x['text'][p:]
        i=j
    return ''.join(('  '*x['indent']+x['text'] if x['text'] else '')+ ('\n' if x['nl'] else '') for x in lines)

@dataclass
class Attribute:
    name: str
    tokens: list
    token: Token

@dataclass
class Block:
    kind: str=''
    labels: list=field(default_factory=list)
    attrs: dict=field(default_factory=dict)
    blocks: list=field(default_factory=list)
    token: Token=None
    path: str=''

    def children(self,kind):return [b for b in self.blocks if b.kind==kind]


def diagnostic(path,token,title,detail,end=None):
    if token is None:
        where='1,1-1'
    else:
        width=max(1,len(token.value.split('\n')[0]))
        where=f'{token.line},{token.col}-{end if end is not None else token.col+width}'
    return AtlasError(f'{path}:{where}: {title}; {detail}')

class Parser:
    def __init__(self,text,path):
        self.text=text;self.path=path;self.ts=lex(text);self.i=0
    def peek(self):return self.ts[self.i] if self.i<len(self.ts) else None
    def pop(self):
        t=self.peek();self.i+=1;return t
    def skipnl(self):
        while self.peek() and self.peek().kind=='nl':self.pop()
    def error(self,t,title,detail,end=None):raise diagnostic(self.path,t,title,detail,end)
    def parse(self):
        root=Block(path=self.path);self.body(root,None);return root
    def body(self,node,open_t):
        while True:
            self.skipnl();t=self.peek()
            if t is None:
                if open_t:self.error(open_t,'Unclosed configuration block','There is no closing brace for this block before the end of the file. This may be caused by incorrect brace nesting elsewhere in this file.')
                return
            if t.value=='}' and open_t:self.pop();return
            if t.kind!='id':self.error(t,'Argument or block definition required','An argument or block definition is required here.')
            name=self.pop();t=self.peek()
            if t and t.value=='=':
                self.pop();et=[];bal=[]
                while self.peek():
                    t=self.peek()
                    if not bal and (t.kind=='nl' or t.value=='}'):break
                    t=self.pop();et.append(t)
                    if t.value in ('[','{','('):bal.append(t.value)
                    elif t.value in (']','}',')'):
                        if bal:bal.pop()
                if not et:self.error(self.peek() or name,'Invalid expression','Expected the start of an expression, but found an invalid expression token.')
                if name.value in node.attrs:self.error(name,'Attribute redefined',f'The argument "{name.value}" was already set. Each argument may be set only once.')
                node.attrs[name.value]=Attribute(name.value,et,name)
                # A one-line block cannot contain another statement after its argument.
