"""A small HCL reader, expression evaluator, and layout engine.

The reader keeps source locations, while the formatter deliberately works on
lexical tokens: formatting is useful even for an unfinished configuration.
"""
from dataclasses import dataclass, field
import json
import os
import re
import math
from errors import AtlasError, quote

@dataclass
class Token:
    value: str
    kind: str
    start: int
    end: int
    line: int
    col: int


def lex(text, comments=False):
    out=[]; i=0; line=1; col=1
    def add(end,kind):
        nonlocal i,line,col
        s=text[i:end]
        if kind not in ('space','comment') or (kind=='comment' and comments):
            out.append(Token(s,kind,i,end,line,col))
        n=s.count('\n')
        if n: line+=n;col=len(s.rsplit('\n',1)[-1])+1
        else: col+=len(s)
        i=end
