        ch=text[i]
        if ch in ' \t\r':
            j=i+1
            while j<len(text) and text[j] in ' \t\r':j+=1
            add(j,'space')
        elif ch=='\n':add(i+1,'nl')
        elif ch=='#' or text.startswith('//',i):
            j=text.find('\n',i)
            add(len(text) if j<0 else j,'comment')
        elif text.startswith('/*',i):
            j=text.find('*/',i+2);add(len(text) if j<0 else j+2,'comment')
        elif ch=='"':
            j=i+1; template_depth=0
            while j<len(text):
                if text[j]=='\\':j+=2;continue
                # Quoted strings within ${...} do not close the outer string.
                if text.startswith('${',j) and (j==0 or text[j-1]!='$'):
                    depth=1;j+=2
                    while j<len(text) and depth:
                        if text[j]=='"':
                            j+=1
                            while j<len(text) and text[j]!='"':j+=2 if text[j]=='\\' else 1
                        elif text[j]=='{':depth+=1
                        elif text[j]=='}':depth-=1
                        j+=1
                    continue
                if text[j]=='"':j+=1;break
                j+=1
            add(min(j,len(text)),'string')
        elif text.startswith('<<',i):
            m=re.match(r'<<-?([\w-]+)[^\n]*\n',text[i:])
            if m:
                tag=m.group(1);end=i+m.end()
                close=re.search(r'(?m)^[ \t]*'+re.escape(tag)+r'[ \t]*(?=\n|$)',text[end:])
                add(end+close.end() if close else len(text),'heredoc')
            else:add(i+2,'op')
        elif ch.isalpha() or ch=='_':
            j=i+1
            while j<len(text) and (text[j].isalnum() or text[j] in '_-'):j+=1
            add(j,'id')
        elif ch.isdigit():
            m=re.match(r'(?:\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)',text[i:])
            add(i+len(m.group()),'num')
        else:
            m=next((x for x in ('...','=>','==','!=','<=','>=','&&','||','::') if text.startswith(x,i)),ch)
            add(i+len(m),'op')
    return out


def _space(prev,cur,prevprev=None):
    if not prev:return False
    a,b=prev.value,cur.value
    if cur.kind=='comment':return True
    if a=='.' or b=='.' or b=='...':return False
    if b in (',',')',']'):return False
    if a in ('(', '['):return False
    if a=='{' and b=='}':return False
    if b=='(' and prev.kind=='id':return False
    if b=='[' and (prev.kind in ('id','string') or a in (']',')')):return False
    if a=='!' or (a=='-' and (prevprev is None or prevprev.value in ('=','(',',','[',':','?','+','-','*','/','!','==','>','<','{'))):return False
