def format_hcl(text):
    tokens=lex(text,True)
    lines=[];cur=[];depth=0
    def flush(newline):
        nonlocal cur,depth
        if not cur:
            lines.append({'text':'','eq':None,'comment':None,'indent':depth,'break':True,'nl':newline});return
