def evaluate(attr,context,path='',type_context=False):
    if isinstance(attr,Attribute):return Expr(attr.tokens,context,path,type_context=type_context).parse()
    return attr


def context_for(roots,variables=None,env=''):
    provided=variables or {};ctx={'var':{},'local':{},'atlas':{'env':env},'data':{}}
    for root in roots:
        for b in root.children('variable'):
            if not b.labels:continue
            name=b.labels[0]
            if name in provided:v=provided[name]
            elif 'default' in b.attrs:v=evaluate(b.attrs['default'],ctx,root.path)
            else:raise AtlasError(f'missing value for required variable {quote(name)}')
            typ=evaluate(b.attrs.get('type'),ctx,root.path) if b.attrs.get('type') else None
            kind=str(typ) if typ else ''
            try:
                if kind=='number':v=float(v);v=int(v) if v.is_integer() else v
                elif kind in ('bool','boolean'):
                    if str(v).lower() not in ('true','false'):raise ValueError()
                    v=str(v).lower()=='true'
                elif kind=='string':
                    if isinstance(v,(list,dict)):raise ValueError()
                    v=value_string(v)
                elif isinstance(typ,Call) and typ.name in ('list','set','map','object','tuple') and isinstance(v,str):
                    v=Expr(lex(v),ctx,root.path).parse()
                    if typ.name in ('list','set','tuple') and not isinstance(v,list):raise ValueError()
            except Exception:
                desc={'number':'a number is required','bool':'a bool is required','string':'string required'}.get(kind,'invalid value')
                raise AtlasError(f'variable {quote(name)}: {desc}')
            ctx['var'][name]=v
    for root in roots:
        for b in root.children('locals'):
            for name,attr in b.attrs.items():ctx['local'][name]=evaluate(attr,ctx,root.path)
    return ctx
