def sql_type(typ):
    if typ.startswith('sql('):
        try:return hcl.decode_string(typ[4:-1])
        except Exception:return typ[4:-1]
    return re.sub(r'\(.*\)','',typ).replace('_',' ')


def base_type(typ):return sql_type(typ).lower()

