    return (identifier(m.group(1)),s[m.end():].strip()) if m else ('','')


def inspect_db(db):
    realm=Realm([Schema('main')]);schema=realm.schemas[0]
    try:rows=db.execute("SELECT name, sql FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY rowid").fetchall()
    except sqlite3.Error as e:raise AtlasError('sqlite: querying schema tables: '+str(e))
    for row in rows:
        name,sql=row['name'],row['sql'] or ''
        t=Table(name);schema.tables.append(t)
        defs=split_top(parentheses(sql)[1:-1]);coldefs={};fkdefs=[]
        for d in defs:
            nm,rest=name_token(d);body=rest
            constraint=''
            if nm.upper()=='CONSTRAINT':constraint,body=name_token(rest);nm,rest=name_token(body)
            if nm.upper()=='CHECK':
                exp=parentheses(body if constraint else d);t.checks.append((constraint,exp));continue
            if nm.upper()=='FOREIGN' or (nm.upper()=='CONSTRAINT' and 'FOREIGN' in rest.upper()):
                mat=re.search(r'FOREIGN\s+KEY\s*(\([^)]*\))\s+REFERENCES\s+("[^"]+"|`[^`]+`|\[[^]]+\]|[^\s(]+)\s*(\([^)]*\))?',body if constraint else d,re.I)
                if mat:fkdefs.append((constraint,[identifier(x) for x in split_top(mat.group(1)[1:-1])],identifier(mat.group(2)),[identifier(x) for x in split_top((mat.group(3) or '()')[1:-1])]))
                continue
            if nm.upper() in ('PRIMARY','UNIQUE'):continue
            # A named CHECK within a column is still a table-level check.
            coldefs[nm]=rest
            for m in re.finditer(r'(?:(?:CONSTRAINT)\s+("[^"]+"|`[^`]+`|\[[^]]+\]|[^\s]+)\s+)?CHECK\s*\(',rest,re.I):
                exp=parentheses(rest,m.end()-1);t.checks.append((identifier(m.group(1) or ''),exp))
            m=re.search(r'(?:(?:CONSTRAINT)\s+("[^"]+"|`[^`]+`|\[[^]]+\]|[^\s]+)\s+)?REFERENCES\s+("[^"]+"|`[^`]+`|\[[^]]+\]|[^\s(]+)\s*(\([^)]*\))?',rest,re.I)
            if m:fkdefs.append((identifier(m.group(1) or ''),[nm],identifier(m.group(2)),[identifier(x) for x in split_top((m.group(3) or '()')[1:-1])]))
        infos=db.execute('PRAGMA table_xinfo('+sqlquote(name)+')').fetchall()
        pk=[]
        for r in infos:
            if r['hidden']==1:continue
            raw=r['type'] or '';typ=type_normal(raw)
            c=Column(r['name'],typ,not r['notnull'],raw,parse_default(r['dflt_value'],typ))
            cd=coldefs.get(c.name,'');c.auto=bool(re.search(r'\bAUTOINCREMENT\b',cd,re.I))
            if r['hidden'] in (2,3):
                m=re.search(r'\bAS\s*\(',cd,re.I)
                c.generated=(parentheses(cd,m.end()-1) if m else '', 'STORED' if r['hidden']==3 else 'VIRTUAL')
            t.columns.append(c)
            if r['pk']:pk.append((r['pk'],Part(column=c.name)))
        t.pk=[p for _,p in sorted(pk,key=lambda x:x[0])]
        try:idxs=list(db.execute('PRAGMA index_list('+sqlquote(name)+')'))
        except sqlite3.Error:idxs=[]
        for r in reversed(idxs):
            iname=r['name'];parts=[];where='';sqlrow=db.execute("SELECT sql FROM sqlite_master WHERE type='index' AND name=?",(iname,)).fetchone();isql=(sqlrow[0] or '') if sqlrow else ''
            mat=re.search(r'\bON\s+(?:"[^"]+"|`[^`]+`|\[[^]]+\]|[^\s(]+)\s*\(',isql,re.I)
            partsraw=split_top(parentheses(isql,mat.end()-1)[1:-1]) if mat else []
            if mat:
                rem=isql[mat.end()-1+len(parentheses(isql,mat.end()-1)):];wm=re.search(r'\bWHERE\s+(.+)',rem,re.I|re.S)
                if wm:where=wm.group(1).rstrip(';').strip()
            for p in db.execute('PRAGMA index_xinfo('+sqlquote(iname)+')'):
                if not p['key']:continue
                if p['cid']==-2:
                    exp=partsraw[p['seqno']] if p['seqno']<len(partsraw) else ''
                    exp=re.sub(r'\s+(?:ASC|DESC)\s*$','',exp,flags=re.I)
                    parts.append(Part(expr=exp,desc=bool(p['desc'])))
                elif p['cid']>=0:parts.append(Part(column=p['name'],desc=bool(p['desc'])))
            if r['origin']=='pk':
                if parts:t.pk=parts
            else:t.indexes.append(Index(iname,parts,bool(r['unique']),where))
        frows=list(db.execute('PRAGMA foreign_key_list('+sqlquote(name)+')'));groups={}
        for r in frows:groups.setdefault(r['id'],[]).append(r)
        for id,rs in groups.items():
            rs=sorted(rs,key=lambda r:r['seq']);cols=[r['from'] for r in rs];table=rs[0]['table'];ref=[r['to'] for r in rs]
            fkname=str(id)
            for cname,fcols,ftable,fref in reversed(fkdefs):
