            if any(x is None for x in ref):
                ref=[r['name'] for r in sorted(db.execute('PRAGMA table_info('+sqlquote(table)+')').fetchall(),key=lambda r:r['pk']) if r['pk']]
            t.fks.append(ForeignKey(fkname,cols,table,ref,rs[0]['on_update'],rs[0]['on_delete']))
        trailing=sql[sql.find('(')+len(parentheses(sql)):]
        t.without_rowid=bool(re.search(r'\bWITHOUT\s+ROWID\b',trailing,re.I));t.strict=bool(re.search(r'\bSTRICT\b',trailing,re.I))
