def ref_last(v):return str(v.parts[-1]) if isinstance(v,hcl.Ref) else str(v)
def get_ref_table(v):
    if isinstance(v,hcl.Ref) and 'column' in v.parts:
        idx=v.parts.index('column');return str(v.parts[idx-1]) if idx else ''
    return ''

def realm_from_hcl(roots,variables=None,env=''):
    realm=Realm(source='hcl');ctx=hcl.context_for(roots,variables,env)
    schemas={}
    for root in roots:
        if root.children('env'):
            raise AtlasError('cannot parse project file '+quote(root.path)+' as a schema file')
        for b in root.children('schema'):
            name=b.labels[-1] if b.labels else ''
            if name not in schemas:schemas[name]=Schema(name);realm.schemas.append(schemas[name])
    def ev(b,key,default=None,typ=False):
        return hcl.evaluate(b.attrs[key],ctx,b.path,typ) if key in b.attrs else default
    def parts(b):
        if 'columns' in b.attrs:return [Part(column=ref_last(x)) for x in ev(b,'columns',[])]
        ps=[]
        for p in b.children('on'):
            ps.append(Part(ref_last(ev(p,'column')) if 'column' in p.attrs else '',ev(p,'expr',''),bool(ev(p,'desc',False))))
        return ps
    for root in roots:
        for b in root.blocks:
            if b.kind not in ('table','view'):continue
            name=b.labels[-1] if b.labels else ''
            sch=ev(b,'schema')
            if sch is None:
                raise AtlasError(f'sqlite: failed converting to *schema.Realm: cannot extract schema name for {b.kind} {quote(name)}: schemahcl: type "schema" was not found in nil reference')
            sn=ref_last(sch)
            if sn not in schemas:
                raise AtlasError(f'sqlite: failed converting to *schema.Realm: cannot find schema {quote(sn)} for table {quote(name)}')
            if b.kind=='view':
                schemas[sn].views.append({'name':name,'as':ev(b,'as',''),'columns':[]});continue
            t=Table(name,sn);schemas[sn].tables.append(t)
            for cb in b.children('column'):
                cn=cb.labels[-1] if cb.labels else ''
                if 'type' not in cb.attrs:raise AtlasError(f'sqlite: failed converting to *schema.Realm: cannot convert table {quote(name)}: specutil: nil type')
                tv=ev(cb,'type',typ=True)
                if isinstance(tv,hcl.Call):
                    if tv.name=='sql':typ='sql('+hquote(tv.args[0])+')'
                    else:typ=tv.name+'('+','.join(hcl.value_string(x) for x in tv.args)+')'
                else:typ=str(tv)
                c=Column(cn,typ,bool(ev(cb,'null',False)))
                if 'default' in cb.attrs:
                    d=ev(cb,'default');c.default=Default(d.args[0],True) if isinstance(d,hcl.Call) and d.name=='sql' else Default(d)
                c.auto=bool(ev(cb,'auto_increment',False));c.comment=ev(cb,'comment','')
                gen=cb.children('as')
                if gen:c.generated=(ev(gen[0],'expr',''),str(ev(gen[0],'type','VIRTUAL')))
