                t.indexes.append(ix)
            for fb in b.children('foreign_key'):
                refs=ev(fb,'ref_columns',[])
                f=ForeignKey(fb.labels[-1] if fb.labels else '',[ref_last(x) for x in ev(fb,'columns',[])],get_ref_table(refs[0]) if refs else '',[ref_last(x) for x in refs],str(ev(fb,'on_update','NO_ACTION')).replace('_',' '),str(ev(fb,'on_delete','NO_ACTION')).replace('_',' '))
                t.fks.append(f)
            for cb in b.children('check'):t.checks.append((cb.labels[-1] if cb.labels else '',ev(cb,'expr','')))
            t.without_rowid=bool(ev(b,'without_rowid',False));t.strict=bool(ev(b,'strict',False));t.comment=ev(b,'comment','')
