def hcl_attr_value(v):
    if isinstance(v,bool):return str(v).lower()
    if v is None:return 'null'
    if isinstance(v,str):return hquote(v)
    return hcl.value_string(v)

def ref(prefix,*parts):
    result=prefix
    for p in parts:
        if re.fullmatch(r'[\w-]+',str(p)) and not str(p)[0:1].isdigit():result+='.'+str(p)
        else:result+='['+hquote(p)+']'
    return result


def emit_attrs(attrs,indent):
    if not attrs:return []
    w=max(len(k) for k,v in attrs)
    return [('  '*indent)+k+(' '*(w-len(k)))+' = '+v for k,v in attrs]


def emit_block(kind,labels,attrs,children=None,indent=0,endattrs=None):
    p='  '*indent
    lines=[p+kind+''.join(' '+hquote(x) for x in labels)+' {']
    lines+=emit_attrs(attrs,indent+1)
    if children:
        for c in children:lines+=c
    if endattrs:lines+=emit_attrs(endattrs,indent+1)
    lines.append(p+'}');return lines


def parts_hcl(ps,indent):
    return [emit_block('on',[],([('desc','true')] if p.desc else [])+([('column',ref('column',p.column))] if p.column else [('expr',hquote(p.expr))]),indent=indent) for p in ps]


def realm_hcl(realm):
    lines=[]
    for s in realm.schemas:
        for t in s.tables:
            children=[]
            for c in t.columns:
                attrs=[('null',str(c.null).lower()),('type',c.type)]
                if c.default is not None:
                    attrs.append(('default','sql('+hquote(c.default.value)+')' if c.default.expr else hcl_attr_value(c.default.value)))
                if c.auto:attrs.append(('auto_increment','true'))
                if c.comment:attrs.append(('comment',hquote(c.comment)))
                kids=[]
                if c.generated:
                    kids.append(emit_block('as',[],[('expr',hquote(c.generated[0])),('type',c.generated[1])],indent=2))
                children.append(emit_block('column',[c.name],attrs,kids,1))
            if t.pk:
                if all(p.column and not p.desc for p in t.pk):
                    children.append(emit_block('primary_key',[],[('columns','['+', '.join(ref('column',p.column) for p in t.pk)+']')],indent=1))
                else:children.append(emit_block('primary_key',[],[],parts_hcl(t.pk,2),1))
            for f in t.fks:
                attrs=[('columns','['+', '.join(ref('column',x) for x in f.columns)+']'),('ref_columns','['+', '.join(ref('table',f.table,'column',x) for x in f.ref)+']'),('on_update',f.on_update.replace(' ','_')),('on_delete',f.on_delete.replace(' ','_'))]
                children.append(emit_block('foreign_key',[f.name],attrs,indent=1))
            for ix in t.indexes:
                attrs=[];kids=[]
                if ix.unique:attrs.append(('unique','true'))
                if all(p.column and not p.desc for p in ix.parts):attrs.append(('columns','['+', '.join(ref('column',p.column) for p in ix.parts)+']'))
                else:kids=parts_hcl(ix.parts,2)
                if ix.where:attrs.append(('where',hquote(ix.where)))
                children.append(emit_block('index',[ix.name],attrs,kids,1))
            for name,expr in t.checks:children.append(emit_block('check',[name] if name else [],[('expr',hquote(expr))],indent=1))
            attrs=[('schema',ref('schema',s.name))]
            if t.comment:attrs.append(('comment',hquote(t.comment)))
            endattrs=[]
            if t.without_rowid:endattrs.append(('without_rowid','true'))
            if t.strict:endattrs.append(('strict','true'))
            lines+=emit_block('table',[t.name],attrs,children,endattrs=endattrs)
        for v in s.views:
            lines+=emit_block('view',[v['name']],[('schema',ref('schema',s.name)),('as',hquote(v['as']))])
    for s in realm.schemas:lines+=emit_block('schema',[s.name],[])
    return '\n'.join(lines)+ ('\n' if lines else '')


def part_json(p):
    d={}
    if p.desc:d['desc']=True
    d['column' if p.column else 'expr']=p.column or p.expr
    return d

def realm_json(realm):
    out={}
    if realm.schemas:out['schemas']=[]
    for s in realm.schemas:
        so={'name':s.name}
        if s.tables:so['tables']=[]
        for t in s.tables:
            to={'name':t.name}
            if t.columns:
                to['columns']=[]
                for c in t.columns:
                    co={'name':c.name}
                    if c.raw:co['type']=c.raw
                    if c.null:co['null']=True
                    if c.comment:co['comment']=c.comment
                    to['columns'].append(co)
            if t.indexes:
                to['indexes']=[]
                for idx in t.indexes:
                    io={'name':idx.name}
                    if idx.unique:io['unique']=True
                    if idx.parts:io['parts']=[part_json(p) for p in idx.parts]
                    to['indexes'].append(io)
            if t.pk:to['primary_key']={'parts':[part_json(p) for p in t.pk]}
            if t.fks:
                to['foreign_keys']=[{'name':f.name,'columns':f.columns,'references':{'table':f.table,'columns':f.ref}} for f in t.fks]
            if t.comment:to['comment']=t.comment
            so['tables'].append(to)
        out['schemas'].append(so)
    return out


def default_sql(c):
    d=c.default
    if d is None:return ''
    v=d.value
    if d.expr:
        # String-affinity literal defaults are represented as strings in SQLite.
        if base_type(c.type) in ('blob',) and re.match(r"[xX]'",str(v)):return sqlquote(v)
        return '('+strip_outer(str(v))+')'
    if isinstance(v,str):return sqlquote(v)
    if v is None:return 'NULL'
    return hcl.value_string(v)


def column_sql(c,inline_pk=False):
    out=bq(c.name)+' '+sql_type(c.type)+(' NULL' if c.null else ' NOT NULL')
    if inline_pk:out+=' PRIMARY KEY AUTOINCREMENT'
    if c.default is not None:out+=' DEFAULT '+default_sql(c)
    if c.generated:out+=' AS ('+strip_outer(c.generated[0])+') '+c.generated[1]
    return out


def table_sql(t,indent=''):
    if not t.columns:raise AtlasError(f'sqlite: table {quote(t.name)} has no columns')
    defs=[];autopk=next((p.column for p in t.pk if any(c.name==p.column and c.auto for c in t.columns)),None)
    for c in t.columns:defs.append(column_sql(c,c.name==autopk))
    if t.pk and not autopk:defs.append('PRIMARY KEY ('+', '.join(bq(p.column)+(' DESC' if p.desc else '') for p in t.pk)+')')
    for f in t.fks:
        fk=('CONSTRAINT '+bq(f.name)+' ' if f.name else '')+'FOREIGN KEY ('+', '.join(bq(x) for x in f.columns)+') REFERENCES '+bq(f.table)+' ('+', '.join(bq(x) for x in f.ref)+')'
        if f.on_update:fk+=' ON UPDATE '+f.on_update
        if f.on_delete:fk+=' ON DELETE '+f.on_delete
        defs.append(fk)
    for name,expr in t.checks:
        defs.append(('CONSTRAINT '+bq(name)+' ' if name else '')+'CHECK ('+strip_outer(expr)+')')
    if indent:sql='CREATE TABLE '+bq(t.name)+' (\n'+',\n'.join(indent+d for d in defs)+'\n)'
    else:sql='CREATE TABLE '+bq(t.name)+' ('+', '.join(defs)+')'
    if t.without_rowid:sql+=' WITHOUT ROWID'
    if t.strict:sql+=', STRICT' if t.without_rowid else ' STRICT'
    return sql


def index_name(t,idx):
    if idx.name.startswith('sqlite_autoindex_'):return t.name+'_'+'_'.join(p.column for p in idx.parts if p.column)
    return idx.name


def index_change(t,idx):
    name=index_name(t,idx)
    parts=', '.join((bq(p.column) if p.column else '('+strip_outer(p.expr)+')')+(' DESC' if p.desc else '') for p in idx.parts)
    cmd='CREATE '+('UNIQUE ' if idx.unique else '')+'INDEX '+bq(name)+' ON '+bq(t.name)+' ('+parts+')'
    if idx.where:cmd+=' WHERE '+idx.where
    return Change(f'Create index {quote(name)} to table: {quote(t.name)}',cmd,'DROP INDEX '+bq(name))


def create_table_changes(t,indent=''):
    return [Change('Create '+quote(t.name)+' table',table_sql(t,indent),'DROP TABLE '+bq(t.name))]+[index_change(t,idx) for idx in t.indexes]


def dependency_order(tables):
    # Preserve input order whenever possible, placing referenced tables first.
    result=[];visiting=set();done=set();by={t.name:t for t in tables}
    def visit(t):
        if t.name in done or t.name in visiting:return
        visiting.add(t.name)
        for f in t.fks:
            if f.table in by:visit(by[f.table])
        visiting.remove(t.name);done.add(t.name);result.append(t)
    for t in tables:visit(t)
    return result


def realm_sql(realm,indent=''):
    changes=[]
    for t in dependency_order(realm.tables):changes+=create_table_changes(t,indent)
    return render_changes(changes)


def render_changes(changes):
    return ''.join('-- '+c.comment+'\n'+c.cmd+';\n' for c in changes)


def compare_columns(a,b):
    def d(c):
        if c.default is None:return None
        s=default_sql(c).strip()
        return strip_outer(s).lower() if s.startswith('(') else s
    return base_type(a.type)==base_type(b.type) and a.null==b.null and d(a)==d(b) and a.auto==b.auto and a.generated==b.generated


def compare_table_shape(a,b):
    return a.pk==b.pk and a.fks==b.fks and [(n,strip_outer(e)) for n,e in a.checks]==[(n,strip_outer(e)) for n,e in b.checks] and a.without_rowid==b.without_rowid and a.strict==b.strict


def compare_realms(old,new,indent='',check_schemas=True):
    if check_schemas and old.schemas and new.schemas:
        on=[s.name for s in old.schemas];nn=[s.name for s in new.schemas]
        if on!=nn:
            raise AtlasError('mismatched HCL and database schemas: '+', '.join(quote(x) for x in on)+' <> '+', '.join(quote(x) for x in nn))
    om={t.name:t for t in old.tables};nm={t.name:t for t in new.tables};changes=[];disable=False
    for t in old.tables:
