            changes.append(Change('Drop '+quote(t.name)+' table','DROP TABLE '+bq(t.name)));disable=True
    for t in dependency_order(new.tables):
        if t.name not in om:changes+=create_table_changes(t,indent);continue
        prev=om[t.name];pc={c.name:c for c in prev.columns};tc={c.name:c for c in t.columns}
        removed=any(c.name not in tc for c in prev.columns)
        modified=any(not compare_columns(pc[c.name],c) for c in t.columns if c.name in pc)
        added=[c for c in t.columns if c.name not in pc]
        rebuild=removed or modified or not compare_table_shape(prev,t) or any(c.generated and c.generated[1]=='STORED' for c in added)
        if rebuild:
            disable=True;temp=copy.deepcopy(t);temp.name='new_'+t.name
            changes.append(Change('Create '+quote(temp.name)+' table',table_sql(temp,indent)))
            common=[c for c in t.columns if c.name in pc and not c.generated]
            cols=', '.join(bq(c.name) for c in common);select=[]
            for c in common:
                if not c.null and pc[c.name].null and c.default is not None:
                    select.append('IFNULL('+bq(c.name)+', '+default_sql(c)+') AS '+bq(c.name))
