        elif p.endswith('.sql'):sqls.append(p)
        else:raise AtlasError('unknown schema file: '+quote(p))
    if hcls and sqls:raise AtlasError('cannot mix HCL and SQL schema files')
    if hcls:
        roots=[]
        for p in hcls:
            try:roots.append(hcl.parse(Path(p).read_text(),p))
            except OSError as e:raise AtlasError('open '+p+': '+e.strerror.lower())
        return realm_from_hcl(roots,variables,env)
    if sqls or not files:
        if not dev_url:raise AtlasError('--dev-url cannot be empty')
        db=open_database('sqlite://:memory:')
        # For directory URLs an optional version limits the replay.
        version=''
        if urls:
            version=urllib.parse.parse_qs(urllib.parse.urlsplit(urls[0]).query).get('version',[''])[0]
        for p in sqls:
            if version and os.path.basename(p).split('_')[0].removesuffix('.sql')>version:continue
