def read_resource(name):
    # This also works when __file__ points into a zip application.
    import pkgutil
    try:
        import zipfile
        root=Path(__file__).parent
        if root.is_dir():return (root/name).read_text()
        with zipfile.ZipFile(sys.argv[0]) as z:return z.read(name).decode()
    except Exception:return ''

def help_text(command):
