def command_path(args):
    # Cobra resolves commands before parsing their local and inherited flags.
    allopts=dict(GLOBALS)
    for opts in OPTIONS.values():allopts.update(opts)
    short={v[1]:(k,v) for k,v in allopts.items() if v[1]}
