    short={spec[1]:key for key,spec in opts.items() if spec[1]}
    values={k:(list(s[2]) if isinstance(s[2],list) else s[2]) for k,s in opts.items()}
    changed=set();pos=[];i=0
    def assign(key,val,flag):
        typ=opts[key][0]
        prefix='invalid argument '+quote(val)+' for '+quote(flag)+' flag: '
        if typ=='bool':
            if val in ('1','t','T','TRUE','true','True'):v=True
            elif val in ('0','f','F','FALSE','false','False'):v=False
            else:raise AtlasError(prefix+'strconv.ParseBool: parsing '+quote(val)+': invalid syntax')
