    if u.scheme!='file':raise AtlasError('unsupported config file driver '+quote(u.scheme))
    path=schema.file_url_path(url)
    if not os.path.exists(path):
        if env or 'config' in flags['_changed']:raise AtlasError(f'config file {quote(path)} was not found: stat {path}: no such file or directory')
        return
