    except OSError as e:raise AtlasError('read '+path+': '+e.strerror.lower())
    root=hcl.parse(text,path);ctx=hcl.context_for([root],flags.get('_vars'),env)
    def vals(b):
        d={k:hcl.evaluate(a,ctx,path) for k,a in b.attrs.items()}
        for ch in b.blocks:
            if ch.kind=='env':continue
            d[ch.kind]=vals(ch)
        return d
    # All expressions are evaluated, even in non-selected environments.
    envs=[]
    for b in root.children('env'):
        d=vals(b)
        for field in ('url','dev'):
            if field in d and not isinstance(d[field],str):raise AtlasError(f'schemahcl: failed reading spec as *cmdapi.Project: value of attr {quote(field)} cannot be read as string: string value is required')
