            if field in d and not isinstance(d[field],list):raise AtlasError(f'schemahcl: failed reading spec as *cmdapi.Project: schemahcl: field is of type slice but attr {quote(field)} is type: string')
        if b.labels and b.labels[0]==env:envs.append(d)
    if env and not envs:raise AtlasError('env '+quote(env)+' not defined in config file')
    if len(envs)>1:raise AtlasError('multiple envs found for '+quote(env))
    if not envs:return
