    defaults={}
    for k,v in [('url','url'),('dev','dev-url'),('schemas','schema'),('exclude','exclude'),('include','include')]:
        if k in e:defaults[v]=e[k]
    src=e.get('src',e.get('schema',{}).get('src') if isinstance(e.get('schema'),dict) else None)
    if src is not None:defaults['to']=src if isinstance(src,list) else [src]
    if command=='schema diff' and 'url' in e:defaults['from']=[e['url']]
    mig=e.get('migration',{})
    if isinstance(mig,dict):
        for k,v in mig.items():
            key={'format':'dir-format','revisions_schema':'revisions-schema','exec_order':'exec-order','baseline':'baseline'}.get(k,k.replace('_','-'))
