    if isinstance(fm,dict):
        g,c=command.split(' ',1)
        if isinstance(fm.get(g),dict) and c in fm[g]:defaults['format']=fm[g][c]
    for k,v in defaults.items():
        if k in flags and k not in flags['_changed']:flags[k]=v


def cached_notice(filename,key,message,seconds):
