    msg='Notice: This Atlas edition lacks support for features such as checkpoints,\ntesting, down migrations, and more. Additionally, advanced database objects such as views, \ntriggers, and stored procedures are not supported. To read more: https://atlasgo.io/community-edition\n\n'+INSTALL
    cached_notice('local-community.json','v1.us',msg,7*86400)


