    cached_notice('community_error.json','last_suggested',msg,86400)


def required(flags,keys):
    missing=[k for k in keys if not flags.get(k) and k not in flags['_changed']]
    if missing:raise AtlasError('required flag(s) '+', '.join(quote(k) for k in missing)+' not set')


def inspect_functions(realm,root):
    def sql(obj,*args):return schema.realm_sql(realm,str(args[0]) if args else '')
    def hcl_fn(obj,*args):raise ValueError("\n'atlas schema inspect' with 'hcl' function is not supported by the community version of Atlas.\n\nInstall the non-community version instead:\n\n\tcurl -sSf https://atlasgo.sh | sh\n\nFor more installtion options, see: https://atlasgo.io/docs#installation")
    return {'json':tpl.json_string,'sql':sql,'mermaid':lambda obj,*a:schema.mermaid(realm),'hcl':hcl_fn}


def run_schema(command,f,args):
    sub=command.split()[1]
    if sub=='fmt':
        for p in (args or ['.']):
            if not os.path.exists(p):raise AtlasError('stat '+p+': no such file or directory')
            if os.path.isdir(p):files=[str(x) for x in sorted(Path(p).iterdir()) if x.is_file() and x.name.endswith('.hcl')]
            else:files=[p] if p.endswith('.hcl') else []
            for file in files:
                try:
                    text=Path(file).read_text();new=hcl.format_hcl(text)
                    if new!=text:Path(file).write_text(new);print(file)
                except OSError as e:raise AtlasError('open '+file+': '+e.strerror.lower())
        return
    if sub=='inspect':
        required(f,['url']);url=f['url'];realm=schema.read_state(url,f.get('dev-url',''),f['_vars'],f.get('env',''))
        realm=schema.apply_exclude(realm,f.get('exclude'))
        if f.get('format'):
            root=tpl.Object({'Realm':tpl.from_realm(realm),'URL':tpl.env_object(url).fields['URL']},'*cmdlog.SchemaInspect',lambda:schema.realm_json(realm))
            out=tpl.render(f['format'],root,inspect_functions(realm,root))
        else:out=schema.realm_hcl(realm)
        sys.stdout.write(out);edition_notice();return
    if sub=='diff':
        required(f,['from','to'])
        fmt=f.get('format','')
        # Template syntax is checked before connecting to a database.
        if fmt:tpl.Renderer(fmt,tpl.Object(),{'sql':lambda *x:''})
        old=schema.read_state(f['from'],f.get('dev-url',''),f['_vars'],f.get('env',''))
        new=schema.read_state(f['to'],f.get('dev-url',''),f['_vars'],f.get('env',''))
        old=schema.apply_exclude(old,f.get('exclude'),f.get('include'));new=schema.apply_exclude(new,f.get('exclude'),f.get('include'))
        changes=schema.compare_realms(old,new)
        if fmt:
            root=tpl.Object({'From':tpl.from_realm(old),'To':tpl.from_realm(new),'Changes':changes},'*cmdlog.SchemaDiff')
            def sqlfmt(obj,*a):return schema.render_changes(schema.compare_realms(old,new,str(a[0]) if a else ''))
            sys.stdout.write(tpl.render(fmt,root,{'sql':sqlfmt}))
        else:sys.stdout.write(schema.render_changes(changes) if changes else 'Schemas are synced, no changes to be made.\n')
        return
    if sub=='clean':
        required(f,['url'])
        for opt in ('dry-run','format'):
            if f.get(opt):abort_edition(command+' --'+opt)
        db=schema.open_database(f['url'],missing='schema');old=schema.inspect_db(db)
        changes=schema.compare_realms(old,schema.Realm([schema.Schema(s.name) for s in old.schemas]))
        if not changes:print('Nothing to drop');db.close();return
        sys.stdout.write('-- Planned Changes:\n'+schema.render_changes(changes));sys.stdout.flush()
        if not f.get('auto-approve') and not confirm():db.close();return
        execute_changes(db,changes);db.close();return
    if sub=='apply':
        required(f,['url'])
        for opt in ('plan','edit'):
            if f.get(opt):abort_edition(command+' --'+opt)
        if f.get('tx-mode') not in ('none','file'):raise AtlasError('unknown tx-mode '+quote(f['tx-mode']))
        if not f.get('to') and not f.get('file'):raise AtlasError('one of flag(s) "file" or "to" is required')
        fmt=f.get('format','')
        if fmt:tpl.Renderer(fmt,tpl.Object(),{'json':tpl.json_string})
        db=schema.open_database(f['url'],missing='schema');old=schema.inspect_db(db)
        urls=f.get('to') or ['file://'+x for x in f.get('file',[])]
        new=schema.read_state(urls,f.get('dev-url',''),f['_vars'],f.get('env',''),db_for_hcl=db)
        old=schema.apply_exclude(old,f.get('exclude'),f.get('include'));new=schema.apply_exclude(new,f.get('exclude'),f.get('include'))
        changes=schema.compare_realms(old,new,'  ')
        if fmt:
            applied=[] if f.get('dry-run') else changes
            pending=changes if f.get('dry-run') else []
            envobj=tpl.env_object(f['url'])
            changesobj=tpl.Object({'Applied':applied,'Pending':pending,'Error':None},'cmdlog.Changes')
            jd={**tpl.jsonable(envobj),'Changes':{}}
            if applied:jd['Changes']['Applied']=[c.cmd for c in applied]
            if pending:jd['Changes']['Pending']=[c.cmd for c in pending]
            root=tpl.Object({'Env':envobj,'Changes':changesobj},'*cmdlog.SchemaApply',jd)
            if not f.get('dry-run'):
                if not f.get('auto-approve') and changes and not confirm():db.close();return
                execute_changes(db,changes)
            out=tpl.render(fmt,root,{'json':tpl.json_string});sys.stdout.write(out)
        elif not changes:print('Schema is synced, no changes to be made')
        else:
            sys.stdout.write('-- Planned Changes:\n'+schema.render_changes(changes));sys.stdout.flush()
            if not f.get('dry-run'):
                if not f.get('auto-approve') and not confirm():db.close();return
                execute_changes(db,changes)
        db.close();return


def execute_changes(db,changes):
    try:
        for c in changes:db.execute(c.cmd)
        db.commit()
    except Exception as e:
        try:db.rollback()
        except Exception:pass
        raise AtlasError(str(e))


def confirm():
    # The terminal prompt accepts the selected default with Enter.
    sys.stdout.write('Use the arrow keys to navigate: ↓ ↑ → ← \n? Are you sure?: \n  ▸ Apply\n    Abort\n');sys.stdout.flush()
    line=sys.stdin.readline()
    if not line:raise AtlasError('^D')
    return line.strip().lower() in ('','y','yes','apply')


def run(args):
    command,rest=command_path(args)
    if command.startswith('!'):
        name=command[1:];msg='unknown command '+quote(name)+' for "atlas"'
        suggestions=[c for c in ROOT if levenshtein(c.lower(),name.lower())<=2 or c.lower().startswith(name.lower())]
        if suggestions:msg+='\n\nDid you mean this?\n'+''.join('\t'+x+'\n' for x in suggestions)
        msg+="\nRun 'atlas --help' for usage."
        raise AtlasError(msg)
    if command=='help':
        topics=[x for x in rest if not x.startswith('-')]
        target=' '.join(topics)
        known=['']+ROOT+[g+' '+c for g,v in GROUPS.items() for c in v]+[g+' '+c for g,v in HIDDEN.items() for c in v]
        if target in known:sys.stdout.write(help_text(target));return
        base=help_text('');usage=base[base.index('Usage:'):];usage=usage[:usage.index('Flags:')]+usage[usage.index('Use "atlas'):]
        sys.stdout.write('Unknown help topic [`'+' '.join(topics)+'`]\n'+usage);return
    f,pos=parse_options(command,rest)
    if f.get('help'):
        sys.stdout.write(help_text(command));return
    if not command or command in GROUPS:
        sys.stdout.write(help_text(command));return
    if command=='version':
        print('atlas unofficial version - development\nhttps://github.com/ariga/atlas/releases/latest\nTo download an official version, visit: https://atlasgo.io/getting-started#installation');return
    if command=='license':print('LICENSE\nAtlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.');return
    if command.startswith('completion '):
        shell=command.split()[1]
        text=read_resource('completion_'+shell+'.txt')
        sys.stdout.write(text);return
    group,sub=command.split(' ',1)
    if sub in HIDDEN.get(group,[]):abort_edition(command)
    if command in ('migrate apply','migrate new','migrate diff','migrate set') and len(pos)>1:raise AtlasError('accepts at most 1 arg(s), received '+str(len(pos)))
    if command=='migrate apply' and pos:
        if not re.fullmatch(r'[+-]?\d+',pos[0]):raise AtlasError('invalid amount argument '+quote(pos[0])+' (invalid syntax). Omit the argument or pass a valid integer instead')
        if int(pos[0])==0:raise AtlasError("cannot apply '0' migration files")
    load_project(f,command)
    if group=='schema':run_schema(command,f,pos)
    elif group=='migrate':
        import migrations
        migrations.run(sub,f,pos)


def levenshtein(a,b):
    prev=list(range(len(b)+1))
    for i,c in enumerate(a):
        row=[i+1]
        for j,d in enumerate(b):row.append(min(row[-1]+1,prev[j+1]+1,prev[j]+(c!=d)))
        prev=row
    return prev[-1]


