    out=[]
    for c in reversed(changes):
        if c.reverse:
            comment='Reverse: '+c.comment
            m=re.match(r'CREATE TABLE `([^`]+)`',c.cmd)
            if m:comment='Drop '+quote(m.group(1))+' table'
            m=re.match(r'CREATE (?:UNIQUE )?INDEX `([^`]+)` ON `([^`]+)`',c.cmd)
            if m:comment='Drop index '+quote(m.group(1))+' from table: '+quote(m.group(2))
