    stem=version+('_'+name if name else '')
    paths=[]
    if d.format=='golang-migrate':
        values=[(stem+'.up.sql',text),(stem+'.down.sql',down)]
    elif d.format=='flyway':
        rest=version+'__'+name if name else version+'__'
        values=[('V'+rest+'.sql',text),('U'+rest+'.sql',down)]
    elif d.format=='goose':values=[(stem+'.sql','-- +goose Up\n'+text+'\n-- +goose Down\n'+down)]
    elif d.format=='dbmate':values=[(stem+'.sql','-- migrate:up\n'+text+'\n-- migrate:down\n'+down)]
    elif d.format=='liquibase':values=[(stem+'.sql','--liquibase formatted sql'+ ('\n'+text if text else ''))]
    else:values=[(stem+'.sql',text)]
    for n,content in values:
