def check_scanner(text,name):
    q='';qpos=0;stack=[];line=False;block=False;i=0
    while i<len(text):
        c=text[i]
        if line:
            if c=='\n':line=False
        elif block:
            if text.startswith('*/',i):block=False;i+=1
        elif q:
            if c==q:
