def reverse_changes(changes):
    out=[]
    for c in reversed(changes):
        if c.reverse:
            comment='Reverse: '+c.comment
            m=re.match(r'CREATE TABLE `([^`]+)`',c.cmd)
            if m:comment='Drop '+quote(m.group(1))+' table'
            m=re.match(r'CREATE (?:UNIQUE )?INDEX `([^`]+)` ON `([^`]+)`',c.cmd)
            if m:comment='Drop index '+quote(m.group(1))+' from table: '+quote(m.group(2))
            out.append(schema.Change(comment,c.reverse))
    return out


def write_migration(d,name='',text='',down=''):
    version=datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%d%H%M%S')
    stem=version+('_'+name if name else '')
    paths=[]
    if d.format=='golang-migrate':
        values=[(stem+'.up.sql',text),(stem+'.down.sql',down)]
    elif d.format=='flyway':
        rest=version+'__'+name if name else version+'__'
        values=[('V'+rest+'.sql',text),('U'+rest+'.sql',down)]
    elif d.format=='goose':values=[(stem+'.sql','-- +goose Up\n'+text+'\n-- +goose Down\n'+down)]
    elif d.format=='dbmate':values=[(stem+'.sql','-- migrate:up\n'+text+'\n-- migrate:down\n'+down)]
    elif d.format=='liquibase':values=[(stem+'.sql','--liquibase formatted sql'+ ('\n'+text if text else ''))]
    else:values=[(stem+'.sql',text)]
    for n,content in values:
        p=d.path/n
        try:p.write_text(content)
        except OSError as e:raise AtlasError('open '+str(p)+': '+e.strerror.lower())
        paths.append(p)
    d.write_hash();return paths


