def diagnostics(old,new,text,positions):
    destructive=[];dependent=[];om={t.name:t for t in old.tables};nm={t.name:t for t in new.tables}
    def position(pattern):
        m=re.search(pattern,text,re.I)
        return m.start() if m else 0
    for t in old.tables:
        if t.name not in nm:
            destructive.append({'Pos':position(r'\bDROP\s+TABLE\b'),'Text':'Dropping table '+quote(t.name),'Code':'DS102','SuggestedFixes':[{'Message':'Add a pre-migration check to ensure table '+quote(t.name)+' is empty before dropping it'}]})
        else:
            nc={c.name:c for c in nm[t.name].columns}
            for c in t.columns:
                if c.name not in nc and not (c.generated and c.generated[1]=='VIRTUAL'):
                    destructive.append({'Pos':position(r'\bALTER\s+TABLE\b'),'Text':'Dropping non-virtual column '+quote(c.name),'Code':'DS103','SuggestedFixes':[{'Message':'Add a pre-migration check to ensure column '+quote(c.name)+' is NULL before dropping it'}]})
    for t in new.tables:
        if t.name not in om:continue
        oc={c.name:c for c in om[t.name].columns}
        for c in t.columns:
            if c.name not in oc and not c.null and c.default is None and not c.generated:
                dependent.append({'Pos':position(r'\bALTER\s+TABLE\b'),'Text':f'Adding a non-nullable {quote(schema.sql_type(c.type))} column {quote(c.name)} will fail in case table {quote(t.name)} is not empty','Code':'MF103'})
    reports=[]
    if destructive:reports.append({'Text':'destructive changes detected','Diagnostics':destructive})
    if dependent:reports.append({'Text':'data dependent changes detected','Diagnostics':dependent})
    return reports,bool(destructive)


