    elif sub=='apply':apply_migrations(f,args)
    elif sub=='set':set_version(f,args)
    elif sub=='diff':diff_migrations(f,args)
    elif sub=='import':import_migrations(f)
    elif sub=='lint':lint_migrations(f)
