import pathlib,json,subprocess,difflib,re
cmds=[]
for fp in pathlib.Path('observations').glob('*.json'):
 try:rows=json.loads(fp.read_text())
 except Exception:continue
 if not isinstance(rows,list):continue
 for row in rows:
  if not isinstance(row,dict) or 'args' not in row:continue
  a=row['args']
  if not a:cmds.append(a);continue
  allowed=a[:2] in [['schema','inspect'],['schema','diff'],['migrate','status'],['migrate','validate'],['migrate','lint']]
  allowed=allowed or '--help' in a or a[0] in ['version','help','license','eval','login','logout','whoami']
  allowed=allowed or a[:2]==['schema','apply'] and '--dry-run' in a
  allowed=allowed or a[:2]==['migrate','apply'] and '--dry-run' in a
  if allowed and a not in cmds:cmds.append(a)
def norm(s):
 s=re.sub(r'0xc[0-9a-f]+','<ptr>',s)
 s=re.sub(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z','<time>',s)
 s=re.sub(r'(?<![\w/])\d+(?:\.\d+)?(?:ms|µs|ns)(?!\w)','<duration>',s)
 return s
fail=0
for a in cmds:
 try:
  x=subprocess.run(['./executable']+a,capture_output=True,text=True,timeout=3,input='');y=subprocess.run(['./executable.new']+a,capture_output=True,text=True,timeout=3,input='')
 except subprocess.TimeoutExpired:continue
 if (x.returncode,norm(x.stdout),norm(x.stderr))!=(y.returncode,norm(y.stdout),norm(y.stderr)):
  fail+=1;print('---',a,'rc',x.returncode,y.returncode)
  for label,old,new in [('stdout',x.stdout,y.stdout),('stderr',x.stderr,y.stderr)]:
   if norm(old)!=norm(new):print(label,''.join(difflib.unified_diff(norm(old).splitlines(True),norm(new).splitlines(True)))[:2500])
print('Compared',len(cmds),'commands;',fail,'differences after normalizing times and pointers')
